const students = [
  { id: 1, name: "小雨", city: "上海", age: 18 },
  { id: 2, name: "小林", city: "北京", age: 19 },
  { id: 3, name: "小周", city: "北京", age: 18 }
];

// filter 会逐行检查 students 表中的每一条记录。
// 当前记录叫 student，它只是‘正在被检查的这一行’。
const result = students.filter((student) => {
  // 只保留 city 等于北京的记录。
  return student.city === "北京";
});

// 最终得到的结果仍然是若干行记录，而不是一段模糊文字。
console.log("住在北京的学生:", result);
